from air_quality import health

def snap(done, remaining, completed=0, failed=0, retry=0):
    # build one-history-per-completed snapshot
    hist=[]
    fails=0
    for i in range(done):
        cp = {"from_cursor":i,"to_cursor":i+1,"next_cursor":i+1,
              "old_done":i,"done":i+1,"delta":1,"remaining":remaining}
        hist.append([i,1,False,False,cp])
    state=[done+remaining, done, remaining]
    summary=[len(hist), done, fails, retry, done, remaining]
    return {"state":state,"history":hist,"pending":[],"hits":[],"summary":summary}

# try single snapshot reconcile
try:
    s=snap(0,3)
    print(health.audit_reconcile([s]))
except Exception as ex:
    print("ERR1", type(ex).__name__, ex)
